script:
TARGETS = {
    "Accounting": ["Learn Accounting"],
    "Buying": ["Learn Procurement"],
    "Selling": ["Learn Sales Management"],
    "Stock": ["Learn Inventory Management"],
    "Manufacturing": ["Learn Manufacturing"],
    "Projects": ["Learn Project Management"],
}

try:
    for workspace_name, labels_to_remove in TARGETS.items():
        if frappe.db.exists("Workspace", workspace_name):
            ws = frappe.get_doc("Workspace", workspace_name)
            ws.shortcuts = [s for s in ws.shortcuts if s.label not in labels_to_remove]
            ws.save(ignore_permissions=True)
    frappe.db.commit()
    frappe.log_error("Learning Shortcuts removed", "Setup Script Success")
except Exception:
    frappe.log_error(frappe.get_traceback(), "Delete Shortcuts Failed")

try:
    TARGET_DOCTYPES = ["Payment Reconciliation", "Process Payment Reconciliation"]
    for dt in TARGET_DOCTYPES:
        # Reusing the logic from Step 3 but for 'Data' type
        name = frappe.db.exists("Property Setter", {"doc_type": dt, "field_name": "default_advance_account", "property": "documentation_url"})
        if name:
            ps = frappe.get_doc("Property Setter", name)
            ps.value = ""
            ps.save(ignore_permissions=True)
        else:
            frappe.get_doc({
                "doctype": "Property Setter",
                "doc_type": dt,
                "doctype_or_field": "DocField",
                "field_name": "default_advance_account",
                "property": "documentation_url",
                "property_type": "Data",
                "value": "",
            }).insert(ignore_permissions=True)
    frappe.db.commit()
    frappe.log_error("Documentation URLs cleared", "Setup Script Success")
except Exception:
    frappe.log_error(frappe.get_traceback(), "Remove Doc URL Failed")

roles_to_disable = [
    "Support Team",
]

try:
    for role_name in roles_to_disable:
        role = frappe.get_doc("Role", role_name)
        role.disabled = 1
        role.save(ignore_permissions=True)

    frappe.db.commit()
    frappe.response["message"] = f"Disabled roles: {', '.join(roles_to_disable)}"

except Exception:
    frappe.log_error(frappe.get_traceback(), "Disable Role Failed")
    frappe.throw("Failed. Check Error Log.")
